from rdkit import Chem
import numpy as np
def unit(v): return v/np.linalg.norm(v)
cm = Chem.MolFromMolFile("complex_final.mol", sanitize=False, removeHs=False)
# complex_final.mol was not written (script died). Rebuild raw by re-running stages? Use complex_raw from previous run.
