N = cm.GetNumAtoms()
cc = cm.GetConformer()
def gp(i): return np.array(cc.GetAtomPosition(i))
p1,p2 = [a.GetIdx() for a in cm.GetAtoms() if a.GetSymbol()=="P"]
print("P idx:", p1, p2)
# identify atoms 15 and 86
for i in (15, 86):
    a = cm.GetAtomWithIdx(i)
    print("atom", i, a.GetSymbol(), "neighbors:", [(nb.GetIdx(), nb.GetSymbol()) for nb in a.GetNeighbors()], "pos", gp(i))
# metal atoms
for i in range(N):
    s = cm.GetAtomWithIdx(i).GetSymbol()
    if s in ("Pd","I"): print("metal", i, s, gp(i))
# all clash pairs < 1.7 A (excluding 1-2 and 1-3)
nbr = {}
for b in cm.GetBonds():
    nbr.setdefault(b.GetBeginAtomIdx(),set()).add(b.GetEndAtomIdx())
    nbr.setdefault(b.GetEndAtomIdx(),set()).add(b.GetBeginAtomIdx())
def is13(i,j):
    return any(j in nbr.get(k,set()) for k in nbr.get(i,set()))
clashes=[]
for i in range(N):
    for j in range(i+1,N):
        if j in nbr.get(i,set()): continue
        if is13(i,j): continue
        dd = np.linalg.norm(gp(i)-gp(j))
        if dd < 1.7:
            clashes.append((dd,i,j,cm.GetAtomWithIdx(i).GetSymbol(),cm.GetAtomWithIdx(j).GetSymbol()))
clashes.sort()
for c in clashes[:30]:
    print("clash %.3f  %d(%s) - %d(%s)" % c)
print("num clashes <1.7:", len(clashes))
